package zw.co.hyperfeeds.support;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController@RequestMapping("/livestock/questions")public class LivestockQuestionController{private final JdbcClient jdbc;private final LivestockGuidanceAssistant ai;public LivestockQuestionController(JdbcClient j,LivestockGuidanceAssistant a){jdbc=j;ai=a;}@PostMapping@ResponseStatus(HttpStatus.CREATED)UUID ask(Authentication a,@Valid@RequestBody Question q){UUID id=UUID.randomUUID();jdbc.sql("insert into livestock_questions(id,user_id,subject,question,status,ai_draft) values(:id,:u,:s,:q,'AWAITING_EXPERT',:draft)").param("id",id).param("u",zw.co.hyperfeeds.identity.CurrentUser.id(a)).param("s",q.subject).param("q",q.question).param("draft",ai.draft(q.subject,q.question)).update();return id;}@GetMapping List<Map<String,Object>>mine(Authentication a){return jdbc.sql("select id,subject,question,status,expert_answer,created_at,answered_at from livestock_questions where user_id=:u order by created_at desc").param("u",zw.co.hyperfeeds.identity.CurrentUser.id(a)).query().listOfRows();}@GetMapping("/review")@PreAuthorize("hasAnyRole('ANIMAL_HEALTH_EXPERT','ADMIN','BRANCH_MANAGER','CUSTOMER_SERVICE')")List<Map<String,Object>>review(Authentication a){boolean restricted=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_BRANCH_MANAGER"));return jdbc.sql("select q.id,q.user_id,q.subject,q.question,q.status,q.ai_draft,q.created_at from livestock_questions q join users customer on customer.id=q.user_id where q.status='AWAITING_EXPERT' and (not :restricted or exists(select 1 from employee_branches eb where eb.user_id=:employee and eb.branch_id=customer.preferred_branch_id)) order by q.created_at").param("restricted",restricted).param("employee",zw.co.hyperfeeds.identity.CurrentUser.id(a)).query().listOfRows();}@PutMapping("/{id}/answer")@PreAuthorize("hasAnyRole('ANIMAL_HEALTH_EXPERT','ADMIN','BRANCH_MANAGER','CUSTOMER_SERVICE')")@Transactional void answer(Authentication a,@PathVariable UUID id,@Valid@RequestBody Answer r){boolean restricted=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_BRANCH_MANAGER"));int n=jdbc.sql("update livestock_questions q set expert_answer=:answer,status='ANSWERED',answered_by=:expert,answered_at=now() from users customer where q.id=:id and q.user_id=customer.id and q.status='AWAITING_EXPERT' and (not :restricted or exists(select 1 from employee_branches eb where eb.user_id=:expert and eb.branch_id=customer.preferred_branch_id))").param("answer",r.answer).param("expert",zw.co.hyperfeeds.identity.CurrentUser.id(a)).param("id",id).param("restricted",restricted).update();if(n==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Question is not awaiting an answer or is outside your branch");UUID user=jdbc.sql("select user_id from livestock_questions where id=:id").param("id",id).query(UUID.class).single();jdbc.sql("insert into notifications(user_id,type,title,body,data) values(:u,'LIVESTOCK_ANSWER','Your livestock question was answered',:body,jsonb_build_object('questionId',:id))").param("u",user).param("body",r.answer).param("id",id.toString()).update();}record Question(@NotBlank@Size(max=200)String subject,@NotBlank@Size(max=5000)String question){}record Answer(@NotBlank@Size(max=10000)String answer){} }
